import java.util.*;
import java.io.*;

public class Main {

    static List<List<Long>> chooseTable = new ArrayList<>();
    static int R, C;

    static long choose(int n, int r) {
        if (n >= chooseTable.size() || r < 0 || r > n) {
            return 0;
        }
        return chooseTable.get(n).get(r);
    }

    static long bit(int x) {
        return 1L << x;
    }

    static void recurse(int L, int N, int a, int na, long req, long excl, long cur, List<Long> sums) {
        if (na > N - L)
            return;
        if (L == N) {
            sums.add(cur);
            return;
        }
        long mask = bit(L);
        if ((req & mask) == 0)
            recurse(L + 1, N, a, na, req, excl, cur, sums);
        if (na > 0 && (excl & mask) == 0) {
            long nxt = cur + choose(a, R - 1) * choose(L - a, R);
            recurse(L + 1, N, a + 1, na - 1, req, excl, nxt, sums);
        }
    }

    static Pair<Long, Long> solve(String pattern) {
        int N = pattern.length();
        long base_value = 0;
        for (int i = 0; i < R + C; i++) {
            base_value += choose(i, R - 1) * choose(N - i - 1, R);
        }
        long min_diff = Long.MAX_VALUE;
        long target = 2 * base_value - choose(N, 2 * R);

        long req_mask = 0, excl_mask = 0;
        long total_score = 0;
        for (int i = 0; i < N; i++) {
            char ch = pattern.charAt(i);
            if (ch == 'A') {
                req_mask |= bit(i);
            } else if (ch == 'B') {
                excl_mask |= bit(i);
            }
        }

        long[][][] dp = new long[R + C + 1][R + C + 1][];
        for (int i = 0; i <= R + C; i++) {
            for (int j = 0; j <= R + C; j++) {
                // Initialize later
            }
        }

        long[][] dpArray = new long[R + C + 1][R + C + 1];
        for (long[] row : dpArray)
            Arrays.fill(row, 0);
        dpArray[0][0] = 1;
        for (int j = 0; j <= R + C; j++) {
            for (int k = 0; k <= R + C; k++) {
                if (j >= R - 1 && k >= R)
                    break;
                if (j < R + C && pattern.charAt(j + k) != 'B')
                    dpArray[j + 1][k] += dpArray[j][k];
                if (k < R + C && pattern.charAt(j + k) != 'A')
                    dpArray[j][k + 1] += dpArray[j][k];
            }
        }
        dp[R + C] = new long[R + C + 1][R + C + 1];
        for (int i = 0; i <= R + C; i++)
            dp[R + C][i] = Arrays.copyOf(dpArray[i], R + C + 1);

        int M = N - C;
        List<List<Long>> asums2 = new ArrayList<>();
        for (int i = 0; i <= R + C; i++)
            asums2.add(new ArrayList<>());

        for (int al = R - 1; al <= R + C; al++) {
            List<Long> sumsList = new ArrayList<>();
            recurse(M, N, al, R + C - al, req_mask, excl_mask, 0, sumsList);
            sumsList.sort(Comparator.reverseOrder());
            asums2.set(al, sumsList);
        }

        for (int a = R - 1; a <= R + C; a++) {
            for (int b = R; b <= R + C; b++) {
                if (a > R - 1 && b > R)
                    continue;
                if (dp[a][b] == 0)
                    continue;
                int L = a + b;
                for (int l = 0; l <= M - L; l++) {
                    int r = R + C - a - l;
                    if (r > N - M || r < 0)
                        continue;
                    List<Long> sums1 = new ArrayList<>();
                    recurse(L, M, a, l, req_mask, excl_mask, 0, sums1);
                    List<Long> sums2 = asums2.get(a + l);
                    Collections.sort(sums1);
                    int p = 0, q = 0;
                    int p2 = 0, q2 = 0;
                    while (p < sums1.size() && q < sums2.size()) {
                        while (p2 < sums1.size() && sums1.get(p2).equals(sums1.get(p)))
                            p2++;
                        while (q2 < sums2.size() && sums2.get(q2).equals(sums2.get(q)))
                            q2++;
                        long total = 2 * (sums1.get(p) + sums2.get(q));
                        long diff = Math.abs(total - target);
                        if (diff < min_diff) {
                            min_diff = diff;
                            total_score = 0;
                        }
                        if (diff == min_diff)
                            total_score += (long) (p2 - p) * (q2 - q) * dp[a][b];
                        if (total > target)
                            q = q2;
                        else
                            p = p2;
                    }
                }
            }
        }
        return new Pair<>(min_diff, total_score);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        String pattern = br.readLine();
        int N = 2 * (R + C);
        while (chooseTable.size() <= N) {
            int size = chooseTable.size();
            List<Long> row = new ArrayList<>(size + 1);
            for (int i = 0; i <= size; i++) {
                if (i == 0 || i == size)
                    row.add(1L);
                else
                    row.add(chooseTable.get(size - 1).get(i - 1) + chooseTable.get(size - 1).get(i));
            }
            chooseTable.add(row);
        }
        Pair<Long, Long> opt = solve(String.join("", Collections.nCopies(N, "?")));
        Pair<Long, Long> score = solve(pattern);
        if (score.first.equals(opt.first))
            System.out.println(score.second);
        else
            System.out.println(0);
    }

    static class Pair<F, S> {
        F first;
        S second;

        Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }
    }
